package com.smartgrading.backend.controller;
import com.smartgrading.backend.dto.*; import com.smartgrading.backend.service.QuestionService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class QuestionController { private final QuestionService service; public QuestionController(QuestionService s){service=s;} @PostMapping("/assignments/{assignmentId}/questions") @ResponseStatus(HttpStatus.CREATED) public QuestionResponse create(@PathVariable Integer assignmentId,@Valid @RequestBody QuestionRequest r){return service.create(assignmentId,r);} @GetMapping("/assignments/{assignmentId}/questions") public List<QuestionResponse> forAssignment(@PathVariable Integer assignmentId){return service.forAssignment(assignmentId);} @PostMapping("/questions") @ResponseStatus(HttpStatus.CREATED) public QuestionResponse legacyCreate(@Valid @RequestBody QuestionRequest r){return service.create(r);} @GetMapping("/questions/assignment/{id}") public List<QuestionResponse> legacyList(@PathVariable Integer id){return service.forAssignment(id);} @PutMapping("/questions/{id}") public QuestionResponse update(@PathVariable Integer id,@Valid @RequestBody QuestionRequest r){return service.update(id,r);} @DeleteMapping("/questions/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Integer id){service.delete(id);} }
